export const meta = {
  name: 't02-hechos-teoria',
  description: 'T02: extraer y verificar los hechos de la teoría T_Prf y censar sus descripciones en el árbol',
  phases: [
    { title: 'Hechos', detail: 'axiomas y lenguaje · Prf, modelo y solidez · titulares · literatura · censo .md · censo .lean' },
    { title: 'Verificar', detail: 'un verificador adversarial por cada barrido, que además busca omisiones' },
  ],
}

const COMUN = `Repositorio RPP: E:/dropbox/github/lean4/ROBINSON_PlusPlus (Lean 4 v4.31.0, sin Mathlib). FOL, su dependencia hermana: E:/dropbox/github/lean4/FOL.
REGLAS: SÓLO LECTURA. No edites ni crees ficheros. NUNCA ejecutes lake, lean, elan ni leanchecker, ni scripts que los llamen (check-*.bash, make). Usa Read, Grep, Glob y órdenes de lectura (grep -n, sed -n, wc).
Cita siempre fichero:línea con las líneas de HOY (mídelas con grep -n o sed -n; no te fíes de números de línea citados en documentos). Distingue MEDIDO (lo has leído en el fichero) de INFERIDO (lo deduces). Escribe en español, conciso y exacto.
Contexto: los titulares (Gödel I/II, Tarski, consistencia) son teoremas sobre el cálculo de Hilbert propio \`Prf\` (ROBINSON_PlusPlus/Meta/Hilbert.lean). \`Prf\` deriva desde la lista \`axioms\` (142 fórmulas, Minimal/Axioms.lean) y añade constructores-esquema (DNE \`p3\`, inducción \`ind\`, inducción de listas \`listInd\`, confinamiento \`qconf\`) para TODA fórmula. La lista \`axioms\` no contiene ningún esquema de inducción; el cálculo \`Prf\` sí. La capa \`⊢\` (Derives) se retiró en ADR-115 (2026-10-02).`

const HECHOS = {
  type: 'object',
  properties: {
    hechos: { type: 'array', items: { type: 'object', properties: {
      id: { type: 'string' },
      afirmacion: { type: 'string' },
      evidencia: { type: 'array', items: { type: 'string' } },
      estado: { type: 'string', enum: ['MEDIDO', 'INFERIDO'] },
      notas: { type: 'string' },
    }, required: ['id', 'afirmacion', 'evidencia', 'estado'] } },
    preguntas_abiertas: { type: 'array', items: { type: 'string' } },
  },
  required: ['hechos'],
}

const VEREDICTO = {
  type: 'object',
  properties: {
    revisados: { type: 'array', items: { type: 'object', properties: {
      id: { type: 'string' },
      veredicto: { type: 'string', enum: ['CONFIRMADO', 'CORREGIDO', 'REFUTADO', 'NO_VERIFICABLE'] },
      correccion: { type: 'string' },
      evidencia: { type: 'array', items: { type: 'string' } },
    }, required: ['id', 'veredicto'] } },
    omisiones: { type: 'array', items: { type: 'object', properties: {
      afirmacion: { type: 'string' },
      evidencia: { type: 'array', items: { type: 'string' } },
      estado: { type: 'string' },
    }, required: ['afirmacion', 'evidencia'] } },
  },
  required: ['revisados', 'omisiones'],
}

const HALLAZGO = { type: 'object', properties: {
  fichero: { type: 'string' },
  linea: { type: 'integer' },
  cita: { type: 'string' },
  clase: { type: 'string', enum: ['FALSO-VIGENTE', 'CIERTO', 'HISTORICO-MARCADO', 'HISTORICO-SIN-MARCA', 'DUDOSO'] },
  motivo: { type: 'string' },
  arreglo: { type: 'string' },
}, required: ['fichero', 'linea', 'cita', 'clase', 'motivo'] }

const CENSO = {
  type: 'object',
  properties: {
    hallazgos: { type: 'array', items: HALLAZGO },
    patrones: { type: 'array', items: { type: 'string' } },
    ficheros_recorridos: { type: 'integer' },
  },
  required: ['hallazgos', 'patrones'],
}

const VEREDICTO_CENSO = {
  type: 'object',
  properties: {
    revisados: { type: 'array', items: { type: 'object', properties: {
      fichero: { type: 'string' },
      linea: { type: 'integer' },
      veredicto: { type: 'string', enum: ['CONFIRMADO', 'RECLASIFICAR', 'ERROR'] },
      clase_correcta: { type: 'string' },
      motivo: { type: 'string' },
    }, required: ['fichero', 'linea', 'veredicto'] } },
    omitidos: { type: 'array', items: HALLAZGO },
  },
  required: ['revisados', 'omitidos'],
}

const CLASES = `Clases: FALSO-VIGENTE = presentado como actual y falso hoy (p. ej. que los titulares/el sujeto de Gödel son «Q», «Q++ sin inducción», «IΣ₁», «sin inducción»; que Prf no tiene inducción; que la extensión de codificación es «conservadora» como hecho probado; que ⊬¬G no existe; que ConsistentH es una suposición). CIERTO = verdadero hoy (p. ej. «la lista axioms / Minimal no contiene esquema de inducción»: eso es CIERTO de la lista). HISTORICO-MARCADO = dentro de un bloque marcado como registro/histórico con fecha (🗄️, «Registro», «histórico», 🗑️, tachado, «(previo …)»). HISTORICO-SIN-MARCA = contenido viejo sin marca que un lector tomaría por actual. DUDOSO = no puedes decidir; di por qué.
Matiz clave: una frase sobre la LISTA (Minimal, axioms, coreAxioms) puede ser cierta; la misma frase sobre la TEORÍA de los titulares (lo que deriva Prf) es falsa, porque Prf tiene ind y listInd para toda fórmula y contiene los 6 axiomas de Peano, luego contiene PA.`

const TAREAS = [
  { key: 'axiomas', titulo: 'Los 142 axiomas y el lenguaje', prompt: `${COMUN}

TAREA · Los 142 axiomas de \`axioms\` y el lenguaje (ROBINSON_PlusPlus/Minimal/Axioms.lean, FOL/FOL/FOL.lean).
1. Cuenta las entradas de los literales \`coreAxioms\`, \`codingAxioms\` y \`axioms\` (léelos; no te fíes de los comentarios). Confirma 34 + 107 = 141 (\`axiomsBase\`) y 142 = 141 + \`ax_axiomsCodeT_def\`, y \`axioms_split\`.
2. Para cada uno de los 34 de \`coreAxioms\`: nombre, línea de su def, contenido en una línea en notación estándar (lee la FÓRMULA real: forall_, De Bruijn, =eq…), y símbolos que usa. Di cuáles son EXACTAMENTE los seis axiomas de Peano de primer orden (0≠Sx; Sx=Sy→x=y; x+0=x; x+Sy=S(x+y); x·0=0; x·Sy=x·y+x) y si alguno tiene una forma distinta de la estándar. ¿Hay algún axioma equivalente a Q3 (x≠0 → ∃y x=Sy), p. ej. vía pred?
3. \`codingAxioms\`: agrúpalos por familia (ax_substtc_*, ax_substtsc_*, ax_liftc_*, ax_liftsc_*, ax_substfc_*, ax_liftfc_*, ax_carc/ax_cdrc, ax_vpf_*, ax_tc_*, ax_runFn_*, ax_allIn_*, ax_chainOk_*, ax_lineWF_*, ax_premsOf_*, ax_lenc_*, ax_nthc_*, y los que no encajen), con la cuenta de cada familia (que sumen 107), qué especifica cada familia en una línea y qué símbolos introduce.
4. El ancla \`ax_axiomsCodeT_def\`: qué dice (informal) y qué símbolos usa.
5. INVENTARIO de símbolos: todo símbolo de función y de relación (con la aridad con que se usa) que aparece en los 142, atravesando las abreviaturas de Lean (zero, succ, add, mul, lt, pair, cons, nil, In, lineWF, forall_3, =eq, numeralM…). Para cada abreviatura: ¿es un símbolo primitivo (Term.func sym!"…" o Formula.atom sym!"…") o una macro/def de Lean que se expande a otros símbolos? Da la línea de la definición. En particular: ¿\`<\` es relación o función? ¿\`In\`? ¿\`lineWF\` es un átomo o una ecuación? ¿\`pair\` es un símbolo o el emparejamiento de Cantor escrito con + y ×?
6. ¿Restringe el tipo \`Formula\` (FOL/FOL/FOL.lean, FormulaG (List Char)) los símbolos o sus aridades? Conclusión: ¿cuál es el lenguaje de las fórmulas de \`Prf\` frente al conjunto finito de símbolos que mencionan los axiomas?
7. Comentarios y docstrings de Minimal/Axioms.lean que describen la teoría (busca al menos «conservador», «definicional», «IΣ», «sin inducción», «PA», «Peano», «Robinson», «Q++»): cita cada uno y di si es cierto hoy. En concreto, «extensión definicional conservadora»: ¿fijan ax_substtc_*, ax_substfc_* y ax_liftfc_* el valor de su símbolo en TODO número, incluidos los que no son códigos bien formados («basura»), o sólo en los códigos? ¿Se prueba la conservatividad en algún sitio del árbol (grep -rn "conservativ" en .lean y .md)?` },
  { key: 'prf', titulo: 'Prf, sus esquemas, el modelo y la solidez', prompt: `${COMUN}

TAREA · El cálculo \`Prf\`, sus esquemas, el modelo y la solidez.
1. ROBINSON_PlusPlus/Meta/Hilbert.lean: lista EXACTA de los constructores de \`Prfᵢ\` y de \`Prf\` (nombre y esquema en notación estándar). Comprueba \`Full.inductionFormula\` (ROBINSON_PlusPlus/Full/Induction.lean), \`listInductionFormula\` y \`confinementFormula\`: ¿son los esquemas estándar? ¿Valen para TODA fórmula, con parámetros (otras variables libres)? ¿Qué símbolos usan (zero, succ, nil, cons)? ¿GEN es irrestricta?
2. En FOL: ¿\`substFormula\` evita la captura (levanta el término sustituido al pasar un ligador)? Da la definición (fichero:línea). Con eso, ¿son correctos los esquemas q1, q2 y leibniz tal como están?
3. Otros cálculos o nociones de demostrabilidad de RPP: \`PrfH\` (prf_to_prfH), \`HilbertSeq\` (Dem/ProvableH), el verificador interno (lineWF, chainOk, provCodeC'), \`prf_to_derivation\`, \`decodeChain_prf\`. Una línea por cada uno: qué es, dónde vive, y si los titulares se enuncian sobre \`Prf\`.
4. Solidez y modelo: \`Estandar\` (definición), \`prf_sound\` (enunciado exacto), \`MNV\` y \`V₀\` (qué son; cómo interpreta el modelo un símbolo que NO aparece en los axiomas: ¿valor por defecto?), \`MN_axioms\`, \`estandar_MN\`, \`consistentH_de\`, \`consistencia\`. ¿El dominio es ℕ con zero/succ/add/mul estándar? ¿Cubre \`prf_sound\` los casos ind y listInd para TODA fórmula, también con símbolos arbitrarios? Ficheros: Meta/SolidezPrf.lean, Meta/ModeloCodigo.lean, Meta/ModeloEstandar.lean, Meta/ModeloCodificacion.lean, Meta/Consistencia.lean.
5. Puente con FOL: ¿hay en RPP algún teorema que relacione \`Prf\` con \`DerivesSet₀\`, \`Derives₀\`, \`Derives₁\`, \`model_existence_iff₀\` o cualquier relación de consecuencia de FOL, en cualquier dirección? (grep -rn en ROBINSON_PlusPlus/ y sondeos/). ¿Qué ofrece FOL (../FOL/FOL/Compacity0.lean y vecinos) que un puente usaría?
6. \`ConsistentH\` (definición) y si el verificador interno se describe como decidible/r.e. en algún sitio.` },
  { key: 'titulares', titulo: 'Los titulares y lo que suponen', prompt: `${COMUN}

TAREA · Los titulares y lo que suponen.
1. Enunciado EXACTO (fichero:línea) de: consistencia, goedel_I, goedel_II, goedel_I_neg, prf_tarski, tarski, tarski_semantico, goedel_first_prf, goedel_second_prf, prf_con_imp_godel, repr_pos'_prf (D1), d2_prf, d3_prf_real, godelCN_indecidible, los teoremas de E10 (G y Con verdaderas en el modelo) y modelo_prov_iff (busca los nombres con grep -rn "theorem NOMBRE"). Su footprint declarado en check-footprints.bash (línea), si tiene fila.
2. Qué son \`godelCN\` y \`consistencyFormula'\` (definiciones): qué predicado de demostrabilidad usan (provCodeC'?), y de qué teoría hablan (axiomsCodeT, el verificador con los tags de Prf).
3. Hipótesis explícitas de cada uno (argumentos, clases).
4. ¿Algún titular habla de una teoría distinta de la de \`Prf\` (extensiones, otra lista de axiomas)? ¿Qué dice exactamente \`goedel_I\`: que ESTE cálculo no deriva G?
5. Qué dicen TEOREMAS-E-HIPOTESIS.md, README.md (líneas 90-150) y GODEL-STATUS.md (líneas 70-115) sobre la teoría de los titulares y sobre lo que se supone; cita las líneas que la describen y di si concuerdan con 1-4.` },
  { key: 'literatura', titulo: 'La literatura', prompt: `${COMUN}

TAREA · Comprobar en la literatura (usa WebSearch y WebFetch; carga esas herramientas con ToolSearch si hace falta) cinco afirmaciones que un documento del proyecto va a usar. Para cada una: la cita exacta (autores, título, revista, volumen, año, páginas, DOI o URL), qué dice exactamente, y tu confianza (alta/media/baja). No inventes metadatos: si no los confirmas, dilo.
1. A. Bezboruah y J. C. Shepherdson, «Gödel's second incompleteness theorem for Q», Journal of Symbolic Logic 41 (1976): ¿qué prueban exactamente (Q no prueba Con_Q, ¿para qué formalización?) y qué advertencia hacen sobre su alcance?
2. ¿Es correcto decir que «Gödel II sobre Q (sin inducción) es un enunciado falso»? ¿Qué es lo que falla en Q: las condiciones de derivabilidad de Hilbert–Bernays–Löb (¿D2? ¿D3?), es decir, la VÍA de la prueba estándar? Fuentes: Hájek y Pudlák, Metamathematics of First-Order Arithmetic (1993); Pudlák, «Cuts, consistency statements and interpretations», JSL 50 (1985); y cualquier otra fiable que encuentres (Visser, Švejdar…).
3. Gödel I sobre Q: Q es esencialmente indecidible (Tarski, Mostowski, Robinson, Undecidable Theories, 1953); Gödel–Rosser vale para toda extensión consistente y r.e. de Q.
4. La axiomatización estándar de PA de primer orden: los seis axiomas (0≠Sx; Sx=Sy→x=y; x+0=x; x+Sy=S(x+y); x·0=0; x·Sy=x·y+x) más el esquema de inducción para toda fórmula; Q3 (x≠0 → ∃y x=Sy) es derivable. Cita una fuente (Kaye, Models of Peano Arithmetic, 1991; Hájek–Pudlák; u otra).
5. IΣ₁ (inducción sólo para fórmulas Σ₁): es el mínimo habitual en el que se prueban D1–D3 para la prueba estándar de Gödel II; ¿basta EA (IΔ₀ + exp)? Cita.` },
  { key: 'censo_md', titulo: 'Censo en los .md', prompt: `${COMUN}

TAREA · CENSO de las descripciones de la teoría objeto en TODOS los .md del repositorio RPP, salvo doc/book/** y doc/registro/** (que no se tocan). Incluye los .md de la raíz, doc/*.md, sondeos/README.md, cuarentena/README.md y cualquier otro .md fuera de esas dos carpetas (Glob "**/*.md").
Patrones mínimos (sin distinguir mayúsculas; añade los que veas necesarios): Q\\+\\+ · Robinson · sin (un )?(esquema|principio)( general)? de inducci · sin inducci · inducción general · IΣ · ISigma · IΔ · \\bPA\\b · Peano · conservador · definicional · teoría objeto · 34 axiomas · 141 · 142 · débil · Minimal ≈ · ≈ Q · T_Prf · teoría de los titulares.
Por cada aparición que DESCRIBA la teoría (no por cada número suelto): fichero, línea, cita de ≤200 caracteres, clase y motivo, y el arreglo que propones (una línea).
${CLASES}
Di también qué ficheros son AUTHORITATIVE (check-doc-sync.bash, variable AUTHORITATIVE, ~líneas 186-187).` },
  { key: 'censo_lean', titulo: 'Censo en los .lean y los scripts', prompt: `${COMUN}

TAREA · CENSO de las descripciones de la teoría objeto en los COMENTARIOS y DOCSTRINGS de ROBINSON_PlusPlus/**/*.lean, en las cabeceras de sondeos/*.lean, y en *.bash, .github/workflows/*.yml, Makefile y lakefile.lean de RPP.
Patrones mínimos (sin distinguir mayúsculas; añade los que veas necesarios): Q\\+\\+ · Robinson · sin (un )?(esquema|principio)( general)? de inducci · sin inducci · inducción general · IΣ · ISigma · IΔ · \\bPA\\b · Peano · conservador · definicional · teoría objeto · 34 axiomas · 141 · 142 · débil · Minimal ≈ · ≈ Q.
Presta atención especial a los docstrings de los titulares y de sus módulos: Meta/Consistencia.lean, Meta/GodelTwoPrf.lean, Meta/SolidezPrf.lean, Meta/Hilbert.lean, Meta/Representability2Prf.lean, Meta/ModeloCodificacion.lean, Meta/TarskiPrf.lean, Meta/SolidezVerificador.lean, Minimal/Axioms.lean, Full/Induction.lean.
Por cada aparición que DESCRIBA la teoría: fichero, línea, cita de ≤200 caracteres, clase y motivo, y el arreglo que propones (una línea).
${CLASES}` },
]

const VERIF_HECHOS = (t, res) => `${COMUN}

Eres un VERIFICADOR ADVERSARIAL. Otro agente hizo esta tarea:
---
${t.prompt.slice(COMUN.length)}
---
Y devolvió estos hechos (JSON):
${JSON.stringify(res)}

Tu trabajo: (a) re-comprobar CADA hecho contra los ficheros (o, si es de literatura, contra las fuentes con WebSearch/WebFetch), con las líneas de hoy. Veredicto por id: CONFIRMADO, CORREGIDO (di la versión correcta), REFUTADO o NO_VERIFICABLE. Sé especialmente duro con las cuentas, con la identificación de los axiomas de Peano (lee la fórmula, no el nombre), con los inventarios de símbolos, con las afirmaciones «ninguno», «todos», «nunca», y con los metadatos bibliográficos. (b) OMISIONES: lo que la tarea pedía y el agente no contestó, o hechos importantes que faltan; aporta su evidencia.`

const VERIF_CENSO = (t, res) => `${COMUN}

Eres un VERIFICADOR ADVERSARIAL y un CRÍTICO DE COMPLETITUD. Otro agente hizo este censo:
---
${t.prompt.slice(COMUN.length)}
---
Y devolvió (JSON):
${JSON.stringify(res)}

Tu trabajo: (a) re-leer con contexto (±10 líneas) TODOS los hallazgos de clase FALSO-VIGENTE, HISTORICO-SIN-MARCA y DUDOSO, y al menos 15 de los demás (todos si son menos de 25), y dar un veredicto: CONFIRMADO, RECLASIFICAR (con la clase correcta) o ERROR (la línea no dice eso). (b) Buscar lo que se le escapó: repite la búsqueda con otras formulaciones («no tiene inducción», «aritmética de Robinson», «teoría débil», «Minimal es», «la teoría», «primitivos», «primAxioms», «IΔ₀», «EA», «Σ₁-inducción», «extensión», «sólido», «consistente», «Asumido») y en ficheros que el censo no citó; devuelve cada omisión como un hallazgo completo con su clase.
${CLASES}`

const res = await pipeline(
  TAREAS,
  t => agent(t.prompt, { label: `hechos:${t.key}`, phase: 'Hechos', schema: (t.key.startsWith('censo') ? CENSO : HECHOS) }),
  (r, t) => r == null ? null : agent(t.key.startsWith('censo') ? VERIF_CENSO(t, r) : VERIF_HECHOS(t, r),
    { label: `verificar:${t.key}`, phase: 'Verificar', schema: (t.key.startsWith('censo') ? VEREDICTO_CENSO : VEREDICTO) })
    .then(v => ({ key: t.key, resultado: r, verificacion: v })),
)
return res.filter(Boolean)
